return $duplicates->map(function (object $duplicate): array {
    $users = User::query()->with('municipio:id,nombre')->where('role', 'taxista')->where('name', $duplicate->name)->where('municipio_id', $duplicate->municipio_id)->orderBy('id')->get(['id', 'name', 'municipio_id', 'licencia', 'nif']);
    $municipios = $users->map(fn(User $user): string => (string) ($user->municipio?->nombre ?? '-'))->unique()->values()->all();
    return ['key' => sprintf('%s / %s', (string) $duplicate->name, implode(', ', $municipios)), 'user_ids' => $users->pluck('id')->map(fn($id): string => (string) $id)->all(), 'names' => $users->pluck('name')->filter()->unique()->values()->all(), 'municipios' => $municipios, 'count' => $users->count()];
})->sortByDesc("count")->values()
